export function seedCards(now = Date.now()): Card[] {
  return SEED.map((row) => ({
    id: row.id,
    rank: row.rank,
    tier: row.tier,
    de: row.de,
    en: row.en,
    article: row.article,
    example_de: row.example_de,
    example_en: row.example_en,
    tags: row.tags,
    // Seed identity and edit time are fixed. Relaunches must never beat an edit or deletion.
    created_at: 0,
    updated_at: 0,
    srs: newSrs(now),
  }))
}

export const SEED_COUNT = SEED.length
